return ['domain'=>'block-inserter-filter','plural-forms'=>'nplurals=1; plural=0;','language'=>'ja','project-id-version'=>'Block Inserter Filter 2.1.1','pot-creation-date'=>'2026-09-14 12:57+0000','po-revision-date'=>'2026-09-14 12:57+0000','x-generator'=>'WP-CLI 2.x','messages'=>['Block Inserter Filter'=>'Block Inserter Filter','Hides individual Gutenberg blocks and embed variations from the block inserter, site-wide. Configurable per block by administrators, with optional GenerateBlocks integration.'=>'Gutenberg のブロックや埋め込みバリエーションをサイト全体でブロック挿入ツールから非表示にします。管理者がブロックごとに設定でき、GenerateBlocks との連携も任意で利用できます。','Jörn Gorres'=>'Jörn Gorres','https://joern.gorres.com'=>'https://joern.gorres.com','Hide Blocks'=>'ブロックを非表示','You do not have permission to do this.'=>'この操作を行う権限がありません。','Registered blocks: %1$d. Currently hidden: %2$d blocks and %3$d embed variations.'=>'登録済みブロック: %1$d 件。現在非表示: ブロック %2$d 件、埋め込みバリエーション %3$d 件。','Checked blocks are removed from the block inserter for all users. Existing content using hidden blocks remains visible – only inserting new instances is blocked.'=>'チェックしたブロックは、すべてのユーザーのブロック挿入ツールから取り除かれます。非表示ブロックを使用している既存のコンテンツはそのまま表示され、新しいインスタンスの挿入だけがブロックされます。','Certain core blocks (Paragraph, Heading, List, Image, Group, Columns) always stay available as a safety net and cannot be hidden here.'=>'一部のコアブロック（段落、見出し、リスト、画像、グループ、カラム）は安全策として常に利用可能で、ここでは非表示にできません。','Search blocks'=>'ブロックを検索','Search blocks…'=>'ブロックを検索…','Choose grouping'=>'グループ化を選択','By category'=>'カテゴリー別','By namespace'=>'名前空間別','No blocks found.'=>'ブロックが見つかりません。','Save Settings'=>'設定を保存','%d hidden'=>'%d 件非表示','Toggle all'=>'すべて切り替え','GenerateBlocks Pro is active. This core block is hidden from the inserter automatically because GenerateBlocks Pro provides an extended variant. If GenerateBlocks Pro is deactivated, the core block reappears automatically.'=>'GenerateBlocks Pro が有効です。GenerateBlocks Pro が拡張版を提供するため、このコアブロックは挿入ツールから自動的に非表示になります。GenerateBlocks Pro を無効化すると、コアブロックは自動的に再表示されます。','Pro variant active'=>'Pro 版が有効','protected'=>'保護済み','Save'=>'保存','Embed variations'=>'埋め込みバリエーション','Variations of the "Embed" block (YouTube, Reddit, Vimeo, …). Checked variations are removed in the editor; the base "Embed" block remains available.'=>'「埋め込み」ブロックのバリエーション（YouTube、Reddit、Vimeo など）。チェックしたバリエーションはエディターから取り除かれ、基本の「埋め込み」ブロックは引き続き利用できます。','Uncategorized'=>'未分類','Settings'=>'設定']];